/// The event queue's limits (§15.6): on overflow the oldest are dropped and the packet carries
/// EVENTS_DROPPED.
pub const EVENT_QUEUE_MAX_EVENTS: usize = 8192;
pub const EVENT_QUEUE_MAX_BYTES: usize = 524288;
/// The main thread plays nothing for an event older than this many ticks (§15.6).
pub const EVENT_STALE_TICKS: u32 = 30;

/// An event's payload (§15.6), one variant per type in events.yaml.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum EventPayload {
    ActionFailed(ActionFailedEvent),
    FlyingText(FlyingTextEvent),
    EntityBuilt(EntityBuiltEvent),
    EntityMined(EntityMinedEvent),
    EntityRotated(EntityRotatedEvent),
    ItemCrafted(ItemCraftedEvent),
    ResearchCompleted(ResearchCompletedEvent),
    Milestone(MilestoneEvent),
    AlertRaised(AlertRaisedEvent),
    PlayerJoined,
    PlayerLeft,
    InputFenced,
    LoopClosed,
    Victory,
}

impl EventPayload {
    pub const fn event_type(&self) -> EventType {
        match self {
            Self::ActionFailed(_) => EventType::ActionFailed,
            Self::FlyingText(_) => EventType::FlyingText,
            Self::EntityBuilt(_) => EventType::EntityBuilt,
            Self::EntityMined(_) => EventType::EntityMined,
            Self::EntityRotated(_) => EventType::EntityRotated,
            Self::ItemCrafted(_) => EventType::ItemCrafted,
            Self::ResearchCompleted(_) => EventType::ResearchCompleted,
            Self::Milestone(_) => EventType::Milestone,
            Self::AlertRaised(_) => EventType::AlertRaised,
            Self::PlayerJoined => EventType::PlayerJoined,
            Self::PlayerLeft => EventType::PlayerLeft,
            Self::InputFenced => EventType::InputFenced,
            Self::LoopClosed => EventType::LoopClosed,
            Self::Victory => EventType::Victory,
        }
    }

    /// The payload's size in bytes (the record's `len`).
    pub const fn len(&self) -> usize {
        match self {
            Self::ActionFailed(_) => 16,
            Self::FlyingText(_) => 20,
            Self::EntityBuilt(_) => 16,
            Self::EntityMined(_) => 16,
            Self::EntityRotated(_) => 16,
            Self::ItemCrafted(_) => 4,
            Self::ResearchCompleted(_) => 4,
            Self::Milestone(_) => 2,
            Self::AlertRaised(_) => 16,
            Self::PlayerJoined => 0,
            Self::PlayerLeft => 0,
            Self::InputFenced => 0,
            Self::LoopClosed => 0,
            Self::Victory => 0,
        }
    }

    pub const fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Decodes the payload of an event of type `ty`, which must fill `bytes` exactly.
    pub fn decode(ty: EventType, bytes: &[u8]) -> DResult<Self> {
        let mut r = Reader::new(bytes);
        let p = match ty {
            EventType::ActionFailed => Self::ActionFailed(ActionFailedEvent::decode(&mut r)?),
            EventType::FlyingText => Self::FlyingText(FlyingTextEvent::decode(&mut r)?),
            EventType::EntityBuilt => Self::EntityBuilt(EntityBuiltEvent::decode(&mut r)?),
            EventType::EntityMined => Self::EntityMined(EntityMinedEvent::decode(&mut r)?),
            EventType::EntityRotated => Self::EntityRotated(EntityRotatedEvent::decode(&mut r)?),
            EventType::ItemCrafted => Self::ItemCrafted(ItemCraftedEvent::decode(&mut r)?),
            EventType::ResearchCompleted => Self::ResearchCompleted(ResearchCompletedEvent::decode(&mut r)?),
            EventType::Milestone => Self::Milestone(MilestoneEvent::decode(&mut r)?),
            EventType::AlertRaised => Self::AlertRaised(AlertRaisedEvent::decode(&mut r)?),
            EventType::PlayerJoined => Self::PlayerJoined,
            EventType::PlayerLeft => Self::PlayerLeft,
            EventType::InputFenced => Self::InputFenced,
            EventType::LoopClosed => Self::LoopClosed,
            EventType::Victory => Self::Victory,
        };
        r.finish("EventPayload")?;
        Ok(p)
    }

    pub fn encode(&self, w: &mut Writer<'_>) -> EResult {
        match self {
            Self::ActionFailed(x) => x.encode(w),
            Self::FlyingText(x) => x.encode(w),
            Self::EntityBuilt(x) => x.encode(w),
            Self::EntityMined(x) => x.encode(w),
            Self::EntityRotated(x) => x.encode(w),
            Self::ItemCrafted(x) => x.encode(w),
            Self::ResearchCompleted(x) => x.encode(w),
            Self::Milestone(x) => x.encode(w),
            Self::AlertRaised(x) => x.encode(w),
            Self::PlayerJoined => Ok(()),
            Self::PlayerLeft => Ok(()),
            Self::InputFenced => Ok(()),
            Self::LoopClosed => Ok(()),
            Self::Victory => Ok(()),
        }
    }

    pub fn dump(&self, d: &mut Dump) {
        d.line("type", self.event_type().name());
        match self {
            Self::ActionFailed(x) => x.dump(d, ""),
            Self::FlyingText(x) => x.dump(d, ""),
            Self::EntityBuilt(x) => x.dump(d, ""),
            Self::EntityMined(x) => x.dump(d, ""),
            Self::EntityRotated(x) => x.dump(d, ""),
            Self::ItemCrafted(x) => x.dump(d, ""),
            Self::ResearchCompleted(x) => x.dump(d, ""),
            Self::Milestone(x) => x.dump(d, ""),
            Self::AlertRaised(x) => x.dump(d, ""),
            Self::PlayerJoined => {}
            Self::PlayerLeft => {}
            Self::InputFenced => {}
            Self::LoopClosed => {}
            Self::Victory => {}
        }
    }
}

/// Writes one EVENTS record (§15.6): the 16-byte header, the payload, zero padding to 4. The header's
/// `type` and `len` come from the payload.
pub fn write_event(w: &mut Writer<'_>, header: &EventHeader, payload: &EventPayload) -> EResult {
    if header.r#type != payload.event_type() {
        return Err(enc_err(ErrorKind::Inconsistent, "EventHeader.type"));
    }
    let start = w.pos();
    let mut h = *header;
    h.len = payload.len() as u16;
    crate::codec::Fixed::write(&h, w, "EventHeader")?;
    payload.encode(w)?;
    w.pad(start, 4);
    Ok(())
}

/// Reads one EVENTS record: the header, the payload (exactly `len` bytes of its type) and the padding.
pub fn read_event(r: &mut Reader<'_>) -> DResult<(EventHeader, EventPayload)> {
    let start = r.pos();
    let h = <EventHeader as crate::codec::Fixed>::read(r, "EventHeader")?;
    let body = r.take(usize::from(h.len), "EventRecord.payload")?;
    let p = EventPayload::decode(h.r#type, body).map_err(|e| DecodeError { at: e.at + start + 16, ..e })?;
    r.pad(start, 4, "EventRecord.padding")?;
    Ok((h, p))
}
